ipValue := 0;
digitsInSeg := 0;
segCount := 0;
curVal := 0;
result := 0;

len := LEN(ipText);

FOR i := 1 TO len DO
    ch := ipText[i];
    IF (ch >= 48) AND (ch <= 57) THEN
        curVal := curVal * 10 + (BYTE_TO_UDINT(ch) - 48);
        IF curVal > 255 THEN
            RETURN;
        END_IF;
        digitsInSeg := digitsInSeg + 1;
