        IF digitsInSeg = 0 THEN
            RETURN;
        END_IF;
        segCount := segCount + 1;
        IF segCount > 4 THEN
            RETURN;
        END_IF;
        result := SHL(result, 8) OR curVal;
        curVal := 0;
        digitsInSeg := 0;
    ELSE
        RETURN;
    END_IF;
END_FOR;

IF digitsInSeg = 0 THEN
    RETURN;
END_IF;

segCount := segCount + 1;
IF segCount <> 4 THEN
    RETURN;
END_IF;

result := SHL(result, 8) OR curVal;
ipValue := result;
```

